import json

def _emit_declared_rows(declarations, facts, prefix, *, publication=False):
    """Standalone serializer kernel: no filesystem, inference or execution."""
    def reject(code, path, actual, expected):
        raise ValueError(json.dumps({"code": code, "field_path": path,
                                     "actual": actual, "expected": expected}, sort_keys=True))

    if not isinstance(facts, dict):
        reject("EFFECT_FACTS_REQUIRED", "$.facts", type(facts).__name__, "object")
    unknown = sorted(set(facts) - set(declarations))
    if unknown:
        reject("EFFECT_FIELD_UNDECLARED", "$.facts", unknown, sorted(declarations))
    payload = {"schema_version": 1}
    for field, rows in declarations.items():
        supplied = facts.get(field, {})
        if not isinstance(supplied, dict):
            reject("EFFECT_FACTS_REQUIRED", "$.facts." + field, type(supplied).__name__, "identity-keyed object")
        expected = [row["identity"] for row in rows]
        if (set(supplied) - set(expected)) or (not publication and set(supplied) != set(expected)):
            reject("EFFECT_FACT_IDENTITIES_MISMATCH", "$.facts." + field, sorted(supplied), expected)
        emitted = []
        for row in rows:
            identity = row["identity"]
            if identity not in supplied:
                continue  # No observed fact; never infer absence or success.
            value = supplied[identity]
            path = "$.facts." + field + "." + identity
            if not isinstance(value, dict) or not value:
                reject("EFFECT_FACTS_REQUIRED", path, value, "nonempty actual fact object")
            if any(key in value for key in ("identity", "artifact_id", "effect_id", "kind", "effect_kind")):
                reject("EFFECT_IDENTITY_OVERRIDE_FORBIDDEN", path, sorted(value), "facts without identity overrides")
            missing = [key for key in row["required_fields"] if value.get(key) is None]
            if field == "produces_artifacts" and not (isinstance(value.get("path"), str) and value["path"].strip()):
                missing.append("path")
            if missing:
                reject("EFFECT_FACT_FIELDS_MISSING", path, sorted(value), sorted(set(missing)))
            emitted.append({"identity": identity, **value})
        if emitted:
            payload[field] = emitted
    if len(payload) == 1:
        return ""  # no supported declaration: fabricate nothing
    return prefix + json.dumps(payload, ensure_ascii=False, separators=(",", ":"), allow_nan=False)

_DECLARED_EFFECT_ROWS = json.loads('{"produces_artifacts": [{"identity": "plan-artifact-7c3b64e012cb94ddd0184b27", "required_fields": []}], "explicit_side_effects": [{"identity": "create_reference_indexes", "required_fields": ["reference_resource_ref", "index_artifacts"]}], "produces_observations": []}')

def emit_effect_evidence(actual_facts):
    return _emit_declared_rows(_DECLARED_EFFECT_ROWS, actual_facts, 'BIOMIND_EFFECT_EVIDENCE_JSON=', publication=True)
import os
import shutil
import subprocess
import sys

REFERENCE = "/public/home/liusiqi/03.毕设/benchmarks/01.测试/04.重测序/Part1.variant_calling/data/genome.fasta"
OUTDIR = "/public/home/liusiqi/03.毕设/benchmarks/biomind_agent_benchmark/runs/task_outputs/session_1789628497/plan_artifacts/01.ref"


def run(cmd, log_path=None):
    proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    if log_path is not None:
        with open(log_path, "w", encoding="utf-8") as fh:
            fh.write("$ " + " ".join(cmd) + "\n")
            fh.write(proc.stdout or "")
    sys.stdout.write("$ " + " ".join(cmd) + "\n")
    sys.stdout.write(proc.stdout or "")
    return proc.returncode


if not os.path.isfile(REFERENCE):
    print(emit_effect_evidence({"explicit_side_effects": {"create_reference_indexes": {
        "reference_resource_ref": REFERENCE,
        "index_artifacts": [],
        "status": "blocked",
        "reason": "reference_fasta not found at bound path",
    }}}))
    raise SystemExit(1)

missing = [name for name in ("samtools", "bwa", "picard") if shutil.which(name) is None]
if missing:
    print(emit_effect_evidence({"explicit_side_effects": {"create_reference_indexes": {
        "reference_resource_ref": REFERENCE,
        "index_artifacts": [],
        "status": "blocked",
        "missing_commands": missing,
    }}}))
    raise SystemExit(1)

os.makedirs(OUTDIR, exist_ok=True)
logdir = os.path.join(OUTDIR, "logs")
os.makedirs(logdir, exist_ok=True)

# Copy the reference into the approved output bundle so the original stays read-only.
local_ref = os.path.join(OUTDIR, "genome.fasta")
shutil.copyfile(REFERENCE, local_ref)

produced = []

rc = run(["samtools", "faidx", local_ref], os.path.join(logdir, "samtools.faidx.log"))
if rc == 0 and os.path.isfile(local_ref + ".fai"):
    produced.append(local_ref + ".fai")

rc = run(["bwa", "index", local_ref], os.path.join(logdir, "bwa.index.log"))
for suffix in (".amb", ".ann", ".bwt", ".pac", ".sa"):
    candidate = local_ref + suffix
    if os.path.isfile(candidate):
        produced.append(candidate)

rc = run(["picard", "CreateSequenceDictionary", "R=" + local_ref, "O=" + os.path.join(OUTDIR, "genome.dict")], os.path.join(logdir, "picard.dict.log"))
dict_path = os.path.join(OUTDIR, "genome.dict")
if rc == 0 and os.path.isfile(dict_path):
    produced.append(dict_path)

if produced:
    print(emit_effect_evidence({
        "produces_artifacts": {"plan-artifact-7c3b64e012cb94ddd0184b27": {"path": OUTDIR}},
        "explicit_side_effects": {"create_reference_indexes": {
            "reference_resource_ref": REFERENCE,
            "index_artifacts": sorted(produced),
            "status": "created",
        }},
    }))
else:
    print(emit_effect_evidence({"explicit_side_effects": {"create_reference_indexes": {
        "reference_resource_ref": REFERENCE,
        "index_artifacts": [],
        "status": "blocked",
        "reason": "no index product was produced; see logs",
    }}}))
    raise SystemExit(1)
